import { memo, useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react'

import { useAtomValue } from 'jotai'

import CancelIcon from '@mui/icons-material/Cancel'
import CheckCircleIcon from '@mui/icons-material/CheckCircle'
import HearingIcon from '@mui/icons-material/Hearing'
import { Box, Button, IconButton, Typography } from '@mui/material'
import type { ButtonProps } from '@mui/material'
import { alpha } from '@mui/material/styles'

import { useIsMobile } from '@/hooks/useIsMobile'
import { useTypedSearchParams } from '@/hooks/useTypedSearchParams'
import { routes } from '@/routes'

import { learnConfigAtom } from '../atoms'
import { useFlashCardQuiz } from '../hooks/useFlashCardQuiz'
import { useTts } from '../lib/tts'
import type { FlashCardItem } from '../types'
import { shuffleArray } from '../utils'

import DrawPadLayout from './DrawPadLayout'
import { QuizContainer, QuizSuspenseWrapper } from './QuizLayout'
import { Answer, Question } from './RenderContext'

export type OneFromManyViewProps = {
  className?: string
}

type Stage = 'Guessing' | 'Studying' | 'Answering'

type Answer = {
  a: string
  correctAnswer?: boolean
}

function makeAnswers(flashCardItems: FlashCardItem[], questionIndex: number): Answer[] {
  const item = flashCardItems[questionIndex]
  const refinedAnswers = flashCardItems.map(({ a }) => a.trim().toUpperCase())
  const uniqueAnswers = Array.from(new Set(refinedAnswers))

  // If there are 4 or fewer unique answers, use them all
  if (uniqueAnswers.length <= 4) {
    return uniqueAnswers.map((a) => ({
      a: flashCardItems.find((i) => i.a.trim().toUpperCase() === a)?.a || a,
      correctAnswer: item.a.trim().toUpperCase() === a,
    }))
  }

  // Otherwise, pick 3 random wrong answers + the correct one
  const wrongAnswers = shuffleArray(flashCardItems.filter((i) => i.a !== item.a))
    .slice(0, 3)
    .map(({ a }) => ({ a }))

  return shuffleArray([...wrongAnswers, { a: item.a, correctAnswer: true }])
}

function OneFromManyViewContent(props: OneFromManyViewProps) {
  const { className } = props
  const { queryParams } = useTypedSearchParams(routes.flashMan.learn.oneFromMany.$config)
  const { owner, repo, path } = queryParams

  const quizState = useFlashCardQuiz({ owner, repo, path })
  const {
    content,
    flashCardItems,
    currentIndex,
    currentItem,
    isComplete,
    recordResult,
    advance,
    restart,
  } = quizState

  // identity를 고정해 memo(DrawPadLayout/DrawPad) 및 하위 힌트 Dialog의
  // 불필요한 리렌더링을 막는다.
  const contentSha = content?.sha
  const noteTarget = useMemo(
    () =>
      owner && repo && path && contentSha && currentItem
        ? {
            owner,
            repo,
            path,
            sha: contentSha,
            lineNo: currentItem.lineNo,
            itemId: currentItem.itemId,
          }
        : null,
    [owner, repo, path, contentSha, currentItem]
  )

  const { isMobile } = useIsMobile()

  const { soundOnLearning, ttsForQuestion, ttsForAnswer, ttsLang } = useAtomValue(learnConfigAtom)
  const playTts = useTts(ttsLang)

  const [stage, setStage] = useState<Stage>('Guessing')
  const [selected, setSelected] = useState<number | undefined>()
  const [focusedIndex, setFocusedIndex] = useState<number | undefined>()

  const refAudioPass = useRef<HTMLAudioElement>(null)
  const refAudioFail = useRef<HTMLAudioElement>(null)

  // 방향키 이동 시에만 스크롤하기 위한 버튼 ref와 플래그 (마우스 hover 시엔 스크롤 안 함)
  const refAnswerButtons = useRef<(HTMLButtonElement | null)[]>([])
  const refScrollOnFocus = useRef(false)

  useEffect(() => {
    refAudioPass.current = new Audio('/sound/pass.mp3')
    refAudioFail.current = new Audio('/sound/4. 뿅.mp3')
    return () => {
      refAudioPass.current = null
      refAudioFail.current = null
    }
  }, [])

  const answers = useMemo(() => {
    if (!currentItem || flashCardItems.length === 0) return []
    return makeAnswers(flashCardItems, currentIndex)
  }, [flashCardItems, currentIndex, currentItem])

  // Auto-play TTS when question changes
  useEffect(() => {
    if (!currentItem) return
    if (isComplete) return
    const play = async () => {
      if (ttsForQuestion) {
        await playTts(currentItem.q)
      }
      if (ttsForAnswer) {
        for (const { a } of answers) {
          await playTts(a)
        }
      }
    }
    play()
  }, [currentIndex, currentItem, ttsForQuestion, ttsForAnswer, answers, playTts, isComplete])

  const replay = useCallback(async () => {
    if (!currentItem) return
    await playTts(currentItem.q)
    if (ttsForAnswer) {
      for (const { a } of answers) {
        await playTts(a)
      }
    }
  }, [currentItem, answers, ttsForAnswer, playTts])

  const handleResult = useCallback(
    (result: 'pass' | 'fail') => {
      recordResult(result)
      setStage('Guessing')
      setSelected(undefined)
      setFocusedIndex(undefined)
      advance()
    },
    [recordResult, advance]
  )

  const handleRestart = useCallback(() => {
    restart()
    setStage('Guessing')
    setSelected(undefined)
    setFocusedIndex(undefined)
  }, [restart])

  // Handle answer selection
  useEffect(() => {
    if (selected !== undefined && answers[selected]) {
      const isCorrect = answers[selected].correctAnswer
      if (soundOnLearning) {
        if (isCorrect) {
          refAudioPass.current?.play()
        } else {
          refAudioFail.current?.play()
        }
      }
      const timeout = setTimeout(() => {
        handleResult(isCorrect ? 'pass' : 'fail')
      }, 1000)
      return () => clearTimeout(timeout)
    }
  }, [selected, answers, handleResult, soundOnLearning])

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (stage === 'Guessing') {
        if (e.key === 's' || e.key === 'S') {
          setStage('Studying')
        } else if (e.key === 'a' || e.key === 'A' || e.key === ' ' || e.key === 'Enter') {
          // Space 기본 동작(페이지 스크롤) 방지
          e.preventDefault()
          setStage('Answering')
        }
      } else if (stage === 'Studying') {
        if (e.key === ' ' || e.key === 'Enter') {
          e.preventDefault()
          handleResult('fail')
        }
      } else if (stage === 'Answering' && selected === undefined) {
        if (answers.length === 0) return
        if (e.key === 'ArrowDown') {
          e.preventDefault()
          refScrollOnFocus.current = true
          // rolling 없이 마지막 항목에서 멈춘다
          setFocusedIndex((prev) =>
            prev === undefined ? 0 : Math.min(prev + 1, answers.length - 1)
          )
        } else if (e.key === 'ArrowUp') {
          e.preventDefault()
          if (focusedIndex === undefined || focusedIndex === 0) {
            // 첫 항목에 다다르면 focus는 유지하고 문제가 보이도록 위로 스크롤
            window.scrollTo({ top: 0, behavior: 'smooth' })
            setFocusedIndex(0)
          } else {
            refScrollOnFocus.current = true
            setFocusedIndex(focusedIndex - 1)
          }
        } else if (e.key === 'Enter' || e.key === ' ') {
          if (focusedIndex === undefined) return
          e.preventDefault()
          setSelected(focusedIndex)
        } else {
          const num = parseInt(e.key)
          if (num >= 1 && num <= answers.length) {
            setFocusedIndex(num - 1)
            setSelected(num - 1)
          }
        }
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [stage, selected, answers.length, focusedIndex, handleResult])

  // 문항이 바뀌면 이전 문항의 버튼 ref를 버린다
  useEffect(() => {
    refAnswerButtons.current.length = answers.length
  }, [answers])

  // 방향키로 focus가 바뀌면 해당 버튼을 viewport 안으로 부드럽게 스크롤
  useEffect(() => {
    if (!refScrollOnFocus.current) return
    refScrollOnFocus.current = false
    if (focusedIndex === undefined) return
    refAnswerButtons.current[focusedIndex]?.scrollIntoView({
      behavior: 'smooth',
      block: 'nearest',
      inline: 'nearest',
    })
  }, [focusedIndex])

  return (
    <QuizContainer
      className={'OneFromManyView ' + (className || '')}
      queryParams={queryParams}
      quizState={quizState}
      onRestart={handleRestart}
    >
      {/* Question Card */}
      <DrawPadLayout
        sx={{ flexGrow: 1 }}
        question={currentItem?.q || ''}
        answer={currentItem?.a || ''}
        clearKey={stage}
        noteTarget={noteTarget}
      >
        {/* Question */}
        <Box sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column', py: 2 }}>
          <Question text={currentItem?.q || ''} />
          {/* Answer (only in Studying stage) */}
          {stage === 'Studying' && (
            <Box
              className="Studying"
              sx={{
                py: 2,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <Answer text={currentItem?.a || ''} sx={{ color: 'primary.main' }} />
            </Box>
          )}
        </Box>
      </DrawPadLayout>

      {/* Controls based on stage */}
      {stage === 'Guessing' && (
        <Box sx={{ display: 'flex', gap: 1 }}>
          {(ttsForQuestion || ttsForAnswer) && (
            <IconButton onClick={replay} size="large">
              <HearingIcon />
            </IconButton>
          )}
          <Button
            variant="outlined"
            fullWidth
            size="large"
            onClick={() => setStage('Studying')}
            sx={{ fontSize: '1.1rem' }}
          >
            익히기 (S)
          </Button>
          <Button
            variant="contained"
            fullWidth
            size="large"
            onClick={() => setStage('Answering')}
            sx={{ fontSize: '1.1rem' }}
          >
            맞추기 (A)
          </Button>
        </Box>
      )}

      {stage === 'Studying' && (
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button
            variant="outlined"
            fullWidth
            size="large"
            onClick={() => {
              window.open(
                `https://translate.google.co.kr/?hl=ko&sl=auto&text=${encodeURIComponent(currentItem?.q || '')}&op=translate`,
                '_blank'
              )
            }}
            sx={{ fontSize: '1rem' }}
          >
            번역
          </Button>
          <Button
            variant="outlined"
            fullWidth
            size="large"
            onClick={() => {
              window.open(
                `https://www.google.com/search?q=${encodeURIComponent(currentItem?.q || '')}`,
                '_blank'
              )
            }}
            sx={{ fontSize: '1rem' }}
          >
            검색
          </Button>
          <Button
            variant="contained"
            fullWidth
            size="large"
            onClick={() => handleResult('fail')}
            sx={{ fontSize: '1.1rem' }}
          >
            {isMobile ? '다음' : '다음 (Space)'}
          </Button>
        </Box>
      )}

      {stage === 'Answering' && (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
          {answers.map((answer, i) => {
            let color: ButtonProps['color'] = 'primary'
            let icon: ReactNode = null
            const focused = selected === undefined && i === focusedIndex
            if (selected !== undefined) {
              if (answer.correctAnswer) {
                color = 'success'
                icon = <CheckCircleIcon />
              } else if (selected === i) {
                color = 'error'
                icon = <CancelIcon />
              }
            }
            return (
              <Button
                key={i}
                ref={(el: HTMLButtonElement | null) => {
                  refAnswerButtons.current[i] = el
                }}
                variant="outlined"
                size="large"
                color={color}
                startIcon={icon}
                disableRipple
                disableFocusRipple
                onMouseEnter={() => {
                  if (selected === undefined) {
                    setFocusedIndex(i)
                  }
                }}
                onClick={() => {
                  if (selected === undefined) {
                    setFocusedIndex(i)
                    setSelected(i)
                  }
                }}
                sx={{
                  justifyContent: 'flex-start',
                  textAlign: 'left',
                  fontSize: '1rem',
                  py: 1.5,
                  overflow: 'auto',
                  // 레이아웃에 영향 없는 inset box-shadow로 포커스 표시 (CLS 없음)
                  '&:focus-visible': { outline: 'none' },
                  backgroundColor: ({ palette }) =>
                    focused ? alpha(palette.primary.main, 0.12) : palette.background.default,
                  border: ({ palette }) => `1px solid ${palette.primary.main}`,
                  boxShadow: ({ palette }) =>
                    focused ? `inset 0 0 0 2px ${palette.primary.main}` : 'none',
                  transition: ({ transitions }) =>
                    transitions.create(['background-color', 'box-shadow'], {
                      duration: transitions.duration.shortest,
                    }),
                }}
              >
                <Answer text={answer.a} />
              </Button>
            )
          })}
        </Box>
      )}

      {/* Keyboard hints */}
      {!isMobile && (
        <Typography variant="caption" color="text.secondary" sx={{ mt: 2, textAlign: 'center' }}>
          {stage === 'Guessing' && 'S: 익히기 | A/Space/Enter: 맞추기'}
          {stage === 'Studying' && 'Space/Enter: 다음'}
          {stage === 'Answering' && '↑/↓: 이동 | Space/Enter: 선택 | 1-4: 답 선택'}
        </Typography>
      )}
    </QuizContainer>
  )
}

function OneFromManyView(props: OneFromManyViewProps) {
  return (
    <QuizSuspenseWrapper>
      <OneFromManyViewContent {...props} />
    </QuizSuspenseWrapper>
  )
}

export default memo(OneFromManyView)
